"""Builds report/appendix.md from the analysis outputs (Appendix A: full tables). Headings are demoted one level.
Run after the analysis: python3 report/build_appendix.py"""
import os
import re

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
PARTS = [("A.1 Layer A", "results_a.md"), ("A.2 Layer B", "results_b.md"), ("A.3 Competence-conditional outcomes", "results_competence.md"),
         ("A.4 Extended engines (secondary)", "results_ext.md")]

out = ["# Appendix A. Full result tables", "",
       "Generated by `report/build_appendix.py` from `analysis/out/`. Numbers in the paper that are not in these tables are counted from the released trial records.", ""]
for title, f in PARTS:
    text = open(os.path.join(ROOT, "analysis", "out", f)).read()
    lines = text.splitlines()
    if lines and lines[0].startswith("# "):
        lines = lines[1:]
    out += [f"## {title}", ""] + [re.sub(r"^(#+) ", lambda m: "#" * (len(m.group(1)) + 1) + " ", l) for l in lines] + [""]
open(os.path.join(ROOT, "report", "appendix.md"), "w").write("\n".join(out))
print(sum(1 for l in out if l.startswith("|---")), "tables")
